    title_teen: 'من الصفر إلى الواحد',
    summary_child: 'بدلاً من تقليد ما فعله الآخرون، يوضح لك هذا الكتاب كيف تفكر في أفكار جديدة تماماً. كن الشخص الذي يصنع أول هاتف طائر بدلاً من مجرد صنع هاتف آخر!',
    summary_teen: 'يقدم بيتر ثيل رؤية حول كيفية بناء شركات تخلق أشياء جديدة. الانتقال من 1 إلى ن يعني التقليد، لكن الانتقال من 0 إلى 1 يعني الابتكار الحقيقي. تعلم كيف تبني احتكاراً إبداعياً يغير العالم.',
    fullContent_child: `## 🚀 0 إلى 1 مقابل 1 إلى ن

- **1 إلى ن:** يعني أخذ شيء موجود وعمل الكثير منه (مثل فتح مطعم بيتزا آخر).
- **0 إلى 1:** يعني صنع شيء لم يره أحد من قبل (مثل اختراع أول طائرة).

---

## 🤫 السر العظيم

كل شركة ناجحة بدأت بسر - شيء تعرفه أنت ولا يعرفه الآخرون. ما هي المشكلة التي يمكنك حلها ولم يحلها أحد بعد؟

---

## 🏰 ابنِ احتكارك الصغير

لا تحاول منافسة الجميع في البداية. ابدأ بسوق صغير جداً وكن الأفضل فيه، ثم توسع تدريجياً.

> **"كل لحظة في العمل تحدث مرة واحدة فقط."**`,
    fullContent_teen: `## 💡 الاحتكار الإبداعي

خلافاً للاعتقاد الشائع، المنافسة الشرسة تدمر الأرباح. الشركات العظيمة هي التي تهرب من المنافسة عبر خلق شيء فريد جداً بحيث لا يوجد له بديل.

---

## ❓ السؤال الصعب

"ما هي الحقيقة المهمة التي يتفق معك فيها قلة من الناس؟" الإجابة على هذا السؤال هي مفتاح بناء عمل تجاري مبتكر.

## 🛠️ الأسس السبعة للنجاح

1. **الهندسة:** هل تصنع تقدماً تكنولوجياً حقيقياً؟
2. **التوقيت:** هل هذا هو الوقت المناسب؟
3. **الاحتكار:** هل تبدأ بسوق صغير وتسيطر عليه؟
4. **الأشخاص:** هل لديك الفريق المناسب؟
5. **التوزيع:** كيف ستبيع منتجك؟
6. **الاستمرارية:** هل ستكون في القمة بعد 10 سنوات؟
7. **السر:** هل وجدت فرصة فريدة لا يراها الآخرون؟

> **"الخطأ الفادح هو البدء بمنافسة الجميع. ابدأ بالسيطرة على شريحة صغيرة."**`,
    lesson_0_child: 'حاول ابتكار أفكار جديدة بدلاً من التقليد.',
