    title_teen: 'الشركة الناشئة المرنة',
    summary_child: 'لا تقضِ شهوراً في صنع شيء قبل أن تسأل أحداً إذا كان يريده! تعلم كيف تصنع نسخة بسيطة من فكرتك، واختبرها مع الأصدقاء، ثم حسنها بناءً على رأيهم.',
    summary_teen: 'يغير إريك ريس طريقة بناء الشركات الناشئة. بدلاً من خطط العمل الطويلة، ركز على "التعلم المصادق عليه" عبر حلقة (ابنِ - قس - تعلم). تعلم كيف تطلق منتجاً أولياً (MVP) وتعدل مسارك بسرعة.',
    fullContent_child: `## 🏗️ ابنِ - قس - تعلم

أكبر خطأ يقع فيه المبتدئون هو قضاء وقت طويل جداً في السر لبناء منتج "مثالي".

**الطريقة الأفضل:**
1. **ابنِ:** اصنع أبسط نسخة من فكرتك (مثل رسم أو نموذج كرتوني).
2. **قس:** أرِه للناس واسألهم: "هل ستشترون هذا؟".
3. **تعلم:** استخدم ما قالوه لتحسين المنتج أو تغيير الفكرة تماماً.

---

## 🍕 المنتج الأولي البسيط (MVP)

إذا كنت تريد فتح مطعم بيتزا، لا تستأجر مكاناً كبيراً فوراً. اصنع بيتزا واحدة في منزلك وبعها لجارك. إذا أعجبته، فأنت على الطريق الصحيح!

> **"الفشل هو فرصة للتعلم بسرعة أكبر."**`,
    fullContent_teen: `## 🔄 ريادة الأعمال هي إدارة

الشركة الناشئة ليست مجرد منتج، بل هي مؤسسة تعمل في ظروف من عدم اليقين الشديد. الطريقة الوحيدة للنجاح هي عبر "التعلم المصادق عليه".

---

## 🛠️ حلقة التغذية الراجعة

الهدف من الشركة الناشئة هو المرور عبر حلقة (Build-Measure-Learn) بأسرع ما يمكن. كلما تعلمت أسرع، زادت فرصك في النجاح قبل أن ينفد مالك.

## 🧭 المحور أم الاستمرار؟ (Pivot or Persevere)

بناءً على البيانات التي تجمعها:
- **المحور:** تغيير الاستراتيجية بالكامل إذا لم تنجح الفكرة الأصلية.
- **الاستمرار:** مواصلة العمل على نفس المسار مع تحسينات بسيطة.

> **"لا تبنِ شيئاً لا يريده أحد، حتى لو بنيته ببراعة."**`,
    lesson_0_child: 'ابدأ بنسخة بسيطة جداً من فكرتك.',
