    title_teen: 'استراتيجية المحيط الأزرق',
    summary_child: 'تخيل أنك في بحر مليء بأسماك القرش الجائعة التي تقاتل على نفس الطعام. هذا هو المحيط الأحمر. يوضح لك هذا الكتاب كيف تسبح بعيداً إلى "المحيط الأزرق" حيث تكون الوحيد هناك ويكون كل الطعام لك!',
    summary_teen: 'بدلاً من التنافس في الأسواق المزدحمة (المحيطات الحمراء)، ركز على خلق مساحات سوق جديدة (المحيطات الزرقاء) حيث لا توجد منافسة. تعلم كيفية جعل المنافسة غير ذات صلة عبر الابتكار في القيمة.',
    fullContent_child: `## 🦈 المحيط الأحمر مقابل 🌊 المحيط الأزرق

- **المحيط الأحمر:** هو المكان الذي يتنافس فيه الجميع على نفس العملاء. تكون المنافسة شرسة والأسعار تنخفض.
- **المحيط الأزرق:** هو المكان الذي تصنع فيه شيئاً مختلفاً تماماً. أنت لا تنافس؛ أنت تقود!

---

## 🎪 مثال: سيرك دو سوليه

السيرك القديم كان مملاً وباهظ الثمن. قام سيرك دو سوليه بحذف الحيوانات (التي كانت تكلف الكثير) وأضاف الموسيقى والقصص الرائعة. لقد صنعوا "محيطاً أزرق" جديداً بالكامل!

---

## 🗺️ خريطة الابتكار

1. **احذف:** الأشياء التي يفعلها الجميع ولكنها ليست ضرورية.
2. **قلل:** الأشياء التي تزيد التكلفة ولكن لا يحبها الأطفال كثيراً.
3. **زد:** الأشياء التي تجعل منتجك رائعاً حقاً.
4. **ابتكر:** شيئاً لم يسبق لأحد أن رآه في مجالك.

> **"أفضل طريقة لهزيمة المنافسة هي التوقف عن محاولة هزيمتها."**`,
    fullContent_teen: `## 🗺️ التفكير خارج المنافسة

المنافسة في الصناعات القائمة تؤدي إلى نمو محدود. استراتيجية المحيط الأزرق تدور حول الابتكار في القيمة: خفض التكاليف مع زيادة القيمة للمشترين في نفس الوقت.

---

## 🛠️ إطار عمل المسارات الستة

للعثور على محيطك الأزرق، ابحث في:
1. الصناعات البديلة.
2. المجموعات الاستراتيجية داخل الصناعة.
3. سلسلة المشترين.
4. عروض المنتجات والخدمات التكميلية.
5. الجاذبية الوظيفية أو العاطفية للمشترين.
6. الزمن (استشراف التوجهات المستقبلية).

## 📊 لوحة الاستراتيجية

ارسم خريطة لمنافسيك وانظر أين يركزون. ثم ابحث عن الفراغات - تلك هي المناطق التي يمكنك فيها خلق قيمة جديدة تماماً.

> **"الابتكار في القيمة هو حجر الزاوية في استراتيجية المحيط الأزرق."**`,
    lesson_0_child: 'لا تقلد الآخرين؛ كن مختلفاً.',
