    summary_child: 'يفحص عادات الشركات ذات الرؤية التي حافظت على عظمتها لعقود من الزمن من خلال الحفاظ على قيمها الجوهرية مع الابتكار المستمر.',
    summary_teen: 'يفحص عادات الشركات ذات الرؤية التي حافظت على عظمتها لعقود من الزمن من خلال الحفاظ على قيمها الجوهرية مع الابتكار المستمر.',
    fullContent_child: `## 🏰 الشركات ذات الرؤية
ما الذي يجعل الشركة تستمر لمدة 100 عام؟ وجد كولينز وبوراس أن الشركات ذات الرؤية مثل ديزني و3M وبوينغ تتشارك في عادات مشتركة تميزها عن غيرها.

## ☯️ الحفاظ على الجوهر / تحفيز التقدم
هذا هو الدرس الأكثر أهمية. الشركة ذات الرؤية لديها "أيديولوجية جوهرية" (قيم وغرض) لا تتغير أبداً. ومع ذلك، فهم يغيرون باستمرار منتجاتهم واستراتيجياتهم وأساليبهم للتكيف مع العالم.

## 🦍 الأهداف الكبيرة والجريئة (BHAGs)
الهدف الكبير والجريء هو هدف ضخم وصعب يستغرق الوصول إليه من 10 إلى 30 عاماً. إنه كبير جداً لدرجة أنه قد يبدو مستحيلاً، لكنه يلهم الجميع في الشركة للعمل معاً.
*مثال: هدف ناسا بوضع إنسان على القمر.*

## 🧪 جرب الكثير من الأشياء واحتفظ بما ينجح
تتصرف الشركات ذات الرؤية مثل الكائنات البيولوجية. إنهم يجربون باستمرار. تفشل العديد من التجارب، ولكن التجارب التي تنجح تصبح هي الشيء الكبير التالي.

## 🎓 الإدارة من الداخل
الشركات ذات الرؤية تروج دائماً تقريباً من الداخل. إنهم يبنون ثقافة "تشبه الطقوس" حيث يؤمن الناس بعمق بالمهمة ويبقون طوال حياتهم المهنية.

> **"الشركات ذات الرؤية هي أكثر بكثير من مجرد شركات ناجحة؛ إنها أيقونات."** — جيم كولينز`,
    fullContent_teen: `## 🏰 الشركات ذات الرؤية
ما الذي يجعل الشركة تستمر لمدة 100 عام؟ وجد كولينز وبوراس أن الشركات ذات الرؤية مثل ديزني و3M وبوينغ تتشارك في عادات مشتركة تميزها عن غيرها.

## ☯️ الحفاظ على الجوهر / تحفيز التقدم
هذا هو الدرس الأكثر أهمية. الشركة ذات الرؤية لديها "أيديولوجية جوهرية" (قيم وغرض) لا تتغير أبداً. ومع ذلك، فهم يغيرون باستمرار منتجاتهم واستراتيجياتهم وأساليبهم للتكيف مع العالم.

## 🦍 الأهداف الكبيرة والجريئة (BHAGs)
الهدف الكبير والجريء هو هدف ضخم وصعب يستغرق الوصول إليه من 10 إلى 30 عاماً. إنه كبير جداً لدرجة أنه قد يبدو مستحيلاً، لكنه يلهم الجميع في الشركة للعمل معاً.
*مثال: هدف ناسا بوضع إنسان على القمر.*

## 🧪 جرب الكثير من الأشياء واحتفظ بما ينجح
تتصرف الشركات ذات الرؤية مثل الكائنات البيولوجية. إنهم يجربون باستمرار. تفشل العديد من التجارب، ولكن التجارب التي تنجح تصبح هي الشيء الكبير التالي.

## 🎓 الإدارة من الداخل
الشركات ذات الرؤية تروج دائماً تقريباً من الداخل. إنهم يبنون ثقافة "تشبه الطقوس" حيث يؤمن الناس بعمق بالمهمة ويبقون طوال حياتهم المهنية.

> **"الشركات ذات الرؤية هي أكثر بكثير من مجرد شركات ناجحة؛ إنها أيقونات."** — جيم كولينز`,
    lesson_0_child: 'حافظ على قيمك الجوهرية مع تطوير استراتيجياتك باستمرار.',
