    fullContent_child: `## ⏱️ سبرينت الأيام الخمسة
تم تطويره في "جوجل فينتشرز"، و**السبرينت** هو اختصار للتعلم دون بناء منتج كامل. في خمسة أيام فقط، تنتقل من مشكلة إلى حل مختبر.

## 📅 الجدول الزمني
- **الأثنين (الخريطة):** حدد المشكلة واختر هدفاً.
- **الثلاثاء (التخطيط):** ابحث عن الكثير من الحلول على الورق.
- **الأربعاء (القرار):** اختر أفضل حل وحوله إلى قصة مصورة.
- **الخميس (النموذج الأولي):** ابنِ نسخة "مزيفة" من منتجك تبدو حقيقية.
- **الجمعة (الاختبار):** اعرض نموذجك الأولي على 5 عملاء حقيقيين وشاهدهم وهم يستخدمونه.

## 🎭 عقلية النموذج الأولي
لا تحتاج إلى منتج يعمل لتتعلم. تحتاج فقط إلى نموذج أولي "معتدل": ليس بسيطاً جداً بحيث يكون مزيفاً، وليس معقداً جداً بحيث يستغرق أسابيع. مجموعة من الشرائح أو نموذج ورقي يمكن أن يكون كافياً.

## 🧪 قوة الرقم 5
الاختبار مع 5 أشخاص فقط سيكشف عن 85% من المشاكل في فكرتك. إنها الطريقة الأكثر فعالية للتعلم.

> **"السبرينت يمنحك قوة خارقة: يمكنك الانتقال سريعاً إلى المستقبل."** — جيك ناب`,
    fullContent_teen: `## ⏱️ سبرينت الأيام الخمسة
تم تطويره في "جوجل فينتشرز"، و**السبرينت** هو اختصار للتعلم دون بناء منتج كامل. في خمسة أيام فقط، تنتقل من مشكلة إلى حل مختبر.

## 📅 الجدول الزمني
- **الأثنين (الخريطة):** حدد المشكلة واختر هدفاً.
- **الثلاثاء (التخطيط):** ابحث عن الكثير من الحلول على الورق.
- **الأربعاء (القرار):** اختر أفضل حل وحوله إلى قصة مصورة.
- **الخميس (النموذج الأولي):** ابنِ نسخة "مزيفة" من منتجك تبدو حقيقية.
- **الجمعة (الاختبار):** اعرض نموذجك الأولي على 5 عملاء حقيقيين وشاهدهم وهم يستخدمونه.

## 🎭 عقلية النموذج الأولي
لا تحتاج إلى منتج يعمل لتتعلم. تحتاج فقط إلى نموذج أولي "معتدل": ليس بسيطاً جداً بحيث يكون مزيفاً، وليس معقداً جداً بحيث يستغرق أسابيع. مجموعة من الشرائح أو نموذج ورقي يمكن أن يكون كافياً.

## 🧪 قوة الرقم 5
الاختبار مع 5 أشخاص فقط سيكشف عن 85% من المشاكل في فكرتك. إنها الطريقة الأكثر فعالية للتعلم.

> **"السبرينت يمنحك قوة خارقة: يمكنك الانتقال سريعاً إلى المستقبل."** — جيك ناب`,
