    summary_child: 'تعلم كيف تبدأ مشروعك الخاص بمبلغ بسيط جداً وتحقق أرباحاً رائعة من خلال هواياتك!',
    summary_teen: 'دليل عملي لبناء عمل تجاري مربح برأس مال ضئيل، بالتركيز على القيمة والمهارات الشخصية.',
    fullContent_child: `## 💰 ابدأ بـ 100 دولار
درس كريس غيلبو 1500 رائد أعمال بدأوا أعمالهم التجارية بدون مال تقريباً. وجد أنك لا تحتاج إلى قرض أو ماجستير إدارة أعمال لتكون ناجحاً.

## 🎯 المعادلة السحرية
**التقارب** (Convergence) هو عندما تلتقي مهاراتك واهتماماتك بما يرغب الآخرون في دفع ثمنه.
*مثال: تحب تنظيم الأشياء + الناس مشغولون = تصبح منظماً محترفاً.*

## 🚀 خطة عمل من صفحة واحدة
لا تغرق في التخطيط. يجب أن تجيب خطتك فقط على:
- ماذا ستبيع؟
- من سيشتريه؟
- كم سيكلف؟
- كيف ستتقاضى أجرك؟

## 🛠️ قائمة مرجعية للإطلاق
الهدف هو الإطلاق بأسرع ما يمكن.
1. حدد عرضك.
2. أنشئ موقعاً بسيطاً أو صفحة تواصل اجتماعي.
3. أخبر كل من تعرفه.
4. اجمع أول دفعة مالية.

## 🤝 الأمر كله يتعلق بالقيمة
العمل التجاري لا يتعلق بـ "الجشع". إنه يتعلق بتقديم القيمة. إذا وجدت طريقة لجعل حياة شخص ما أسهل أو أفضل، فلديك عمل تجاري.

> **"أهم شيء هو أن تبدأ فحسب."** — كريس غيلبو`,
