    fullContent_child: `## 🏃‍♂️ سرعة التعلم
في الشركات الناشئة، أهم شيء هو مدى سرعتك في التعلم. يقدم آش موريا مخططاً لبناء منتجات يريدها الناس حقاً.

## 📝 مخطط Lean Canvas
تم تعديله من مخطط نموذج العمل التجاري، ويركز **Lean Canvas** على أكبر المخاطر للشركات الناشئة:
1. **المشكلة:** ما هي أهم 3 مشكلات؟
2. **الحل:** كيف ستحلها؟
3. **القيمة الفريدة:** لماذا أنت مختلف؟
4. **الميزة غير العادلة:** ما الذي لا يمكن نسخه بسهولة؟
5. **شرائح العملاء:** من هو هدفك؟
6. **المقاييس الرئيسية:** كيف تقيس النجاح؟
7. **القنوات:** كيف تصل للعملاء؟
8. **هيكل التكاليف:** ما هي تكاليفك؟
9. **مصادر الإيرادات:** كيف تجني المال؟

## 🚫 توقف عن بناء أشياء لا يريدها أحد
تفشل معظم الشركات الناشئة لأنها تبني شيئاً لا يريده أحد. قبل أن تكتب سطراً واحداً من البرمجيات، اخرج وقم بإجراء مقابلة مع 10-20 عميلاً محتملاً. اسألهم عن مشاكلهم، وليس عن حلك.

## 🔄 التعديل (Pivot) أو الاستمرار
إذا أظهرت مقابلاتك أن الناس ليس لديهم المشكلة التي تحاول حلها، فقم بتغيير خطتك (Pivot). إذا كان لديهم، فاستمر (Persevere) وابنِ نموذجاً أولياً صغيراً.

> **"منتجك ليس هو المنتج. نموذج عملك هو المنتج."** — آش موريا`,
