    fullContent_child: `## 👟 أيام "بلو ريبون"
قبل أن تصبح "نايكي"، كانت الشركة تسمى "Blue Ribbon Sports". بدأ فيل نايت ببيع أحذية الجري اليابانية من صندوق سيارته. استغرق الأمر سنوات من النضال والاقتراب من الإفلاس قبل أن يصبحوا ناجحين.

## 🏃‍♂️ لا تتوقف
نصيحة نايت بسيطة: استمر في التقدم. لا تتوقف. حتى عندما لا تملك المال، وعندما تكرهك البنوك، وعندما يحاول منافسوك مقاضاتك. إذا لم تتوقف، فلا يمكنك الخسارة.

## 🤝 فريق "بايفيس" (Buttfaces)
كان فريق نايت المبكر مجموعة من غير المتكيفين الذين سماهم "بايفيس". كانوا أشخاصاً لا يخشون الجدال معه وإخباره بأنه مخطئ. كان هذا الصدق والثقة ضروريين لبقاء نايكي.

## 🏁 خط النهاية
العمل التجاري لا يتعلق فقط بتحقيق الأرباح؛ بل يتعلق بالمطاردة. يتعلق بالإيمان بشيء ما (مثل فكرة أن الجميع يجب أن يمتلكوا أحذية جري رائعة) ورفض التخلي عن هذا الاعتقاد.

> **"الجبناء لم يبدأوا أبداً، والضعفاء ماتوا في الطريق. هذا يتركنا نحن، سيداتي وسادتي. نحن."** — فيل نايت`,
