    summary_teen: 'السيرة الذاتية المعتمدة لمؤسس شركة آبل، بناءً على أكثر من أربعين مقابلة مع جوبز ومئات مع أصدقائه ومنافسيه.',
    fullContent_child: `##  تقاطع الفنون والتكنولوجيا
آمن ستيف جوبز بأن أعظم الابتكارات تحدث عندما تلتقي التكنولوجيا مع الفنون الحرة. لم يكن مجرد رجل أعمال؛ بل كان فناناً استخدم السيليكون والزجاج كوسيط للتعبير عن فنه.

## 🌀 مجال تشويه الواقع (Reality Distortion Field)
امتلك جوبز قدرة أسطورية على دفع الناس إلى أبعد مما يعتقدون أنه ممكن. من خلال رفضه لقبول كلمة "لا" أو "هذا مستحيل"، أجبر فرقه على ابتكار منتجات ثورية مثل "ماكنتوش" و "آيفون" في جداول زمنية مستحيلة.

## 🎯 قوة التركيز
عندما عاد جوبز إلى آبل في عام 1997، قام بتقليص خط الإنتاج من عشرات العناصر إلى أربعة فقط. كان يؤمن بأن التركيز يعني قول "لا" لمئات الأفكار الجيدة الأخرى حتى تتمكن من التركيز على الأفكار العظيمة القليلة.

## ✨ البساطة والتصميم
كان جوبز مهووساً بكل التفاصيل، حتى الأجزاء الداخلية للكمبيوتر التي لن يراها المستخدم أبداً. كان يؤمن بأن التصميم ليس مجرد شكل خارجي؛ بل هو كيف تعمل الأشياء معاً بانسجام.

> **"ابق جائعاً.. ابق طموحاً."** — ستيف جوبز`,
