    summary_child: 'القصة الحميمة للمبتكر المبدع الذي كسر كل القواعد ليقود العالم إلى عصر السيارات الكهربائية، واستكشاف الفضاء الخاص، والذكاء الاصطناعي.',
    summary_teen: 'القصة الحميمة للمبتكر المبدع الذي كسر كل القواعد ليقود العالم إلى عصر السيارات الكهربائية، واستكشاف الفضاء الخاص، والذكاء الاصطناعي.',
    fullContent_child: `## 🚀 المهمة إلى المريخ
يتحرك إيلون ماسك بهدف واحد: جعل البشرية جنساً متعدد الكواكب. تغذي هذه الرؤية عمله في SpaceX و Tesla، مما يدفعه لتحمل مخاطر قد يراها الآخرون جنونية.

## ⚙️ الخوارزمية (The Algorithm)
في مصانعه، يتبع ماسك عملية من 5 خطوات يطلق عليها "الخوارزمية":
1. **شكك في كل مطلب:** يجب أن يرتبط كل مطلب باسم الشخص الذي وضعه.
2. **احذف أي جزء أو عملية يمكنك حذفها:** إذا لم تعد إضافة 10% مما حذفته، فأنت لم تحذف بما يكفي.
3. **بسط وحسن:** لا تحسن شيئاً لا ينبغي أن يكون موجوداً أصلاً.
4. **سرع زمن الدورة:** انطلق بشكل أسرع.
5. **أتمت:** فقط بعد الانتهاء من الخطوات الأربع الأولى.

## 🧠 التفكير من المبادئ الأولى (First Principles)
معظم الناس يفكرون بالقياس (يفعلون الشيء لأنه تم فعله من قبل). ماسك يفكر من "المبادئ الأولى". يفكك الأشياء إلى أساسياتها الفيزيائية ويعيد بناءها. هكذا جعل الصواريخ أرخص بـ 10 مرات.

## 🔥 الكثافة الجادة (Hardcore Intensity)
يؤمن ماسك بأن "الإحساس بالإلحاح" هو أهم صفة للشركات الناشئة. يتوقع من فرقه العمل بوتيرة "جادة جداً"، مؤمناً بأن القيود والضغط يؤديان إلى أفضل الابتكارات.

> **"إذا كان الشيء مهماً بما يكفي، يجب عليك المحاولة حتى لو كانت النتيجة المحتملة هي الفشل."** — إيلون ماسك`,
