    summary_child: 'إطار عمل لتوضيح رسالة علامتك التجارية باستخدام العناصر السبعة للقصص العظيمة لإشراك العملاء.',
    summary_teen: 'إطار عمل لتوضيح رسالة علامتك التجارية باستخدام العناصر السبعة للقصص العظيمة لإشراك العملاء.',
    fullContent_child: `## 📖 إطار عمل StoryBrand
تفشل معظم العلامات التجارية لأن رسالتها معقدة للغاية. يوضح دونالد ميلر كيفية استخدام القوة القديمة للقصة لجعل رسالتك واضحة وجذابة.

## 🧙‍♂️ أنت هو المرشد
في كل فيلم عظيم، هناك بطل في مأزق. ثم يظهر **مرشد** (Guide) يقدم له خطة ويدعوه للعمل. علامتك التجارية يجب أن تكون هي المرشد، وليس البطل.

## 🗺️ إطار العمل SB7
1. **شخصية:** العميل.
2. **لديها مشكلة:** ما الذي يعانون منه؟
3. **وتلتقي بمرشد:** علامتك التجارية.
4. **يقدم لها خطة:** خطوات بسيطة للمتابعة.
5. **ويدعوها للعمل:** اشترِ الآن!
6. **مما يساعدها على تجنب الفشل:** ما المخاطر؟
7. **وينتهي بالنجاح:** كيف ستبدو حياتهم بعد ذلك؟

## 🧼 وضح رسالتك
إذا تسببت في ارتباك العميل، فسوف تخسره. يجب أن يكون موقعك الإلكتروني وتسويقك بسيطاً لدرجة أن أي شخص يمكنه فهم ما تقدمه خلال 5 ثوانٍ فقط.

> **"إذا جعلت العميل يرتبك، فسوف تخسره."** — دونالد ميلر`,
