    summary_child: 'يستكشف كيف تؤثر عواطفنا وتحيزاتنا وأناؤنا على قراراتنا المالية، وكيفية بناء الثروة من خلال فهم السلوك البشري.',
    summary_teen: 'يستكشف كيف تؤثر عواطفنا وتحيزاتنا وأناؤنا على قراراتنا المالية، وكيفية بناء الثروة من خلال فهم السلوك البشري.',
    fullContent_child: `## 🧠 المال ليس مجرد رياضيات
في المدرسة، نتعلم أن التمويل يتعلق بالمعادلات والبيانات. ولكن في العالم الحقيقي، المال يتعلق بـ **السلوك**. يشرح مورغان هاوسل أن كيفية تصرفك أهم بكثير من مدى ذكائك.

## ⏳ سر وارن بافيت
يركز معظم الناس على عوائد استثمارات بافيت. لكن سره الحقيقي هو الوقت. بدأ الاستثمار منذ أن كان في العاشرة من عمره. تم تكوين 99% من ثروته بعد عيد ميلاده الخمسين. هذه هي قوة التراكم.

## 📉 الثراء مقابل البقاء ثرياً
يتطلب الثراء المخاطرة والتفاؤل. أما البقاء ثرياً فيتطلب العكس: التواضع، والخوف، والتركيز على البقاء. يجب أن تكون "غير قابل للكسر مالياً" لتسمح للتراكم بالقيام بعمله.

## 🛋️ المنطق المعقول > المنطق الصارم
لا تحاول أن تكون روبوتاً عقلانياً تماماً في تعاملك مع المال. اهدف إلى أن تكون **معقولاً**. الخطة التي تسمح لك بالنوم بسلام في الليل أفضل من الخطة "المثالية" التي تتخلى عنها أثناء انهيار السوق.

> **"الأداء الجيد في المال له علاقة قليلة بمدى ذكائك وعلاقة كبيرة بكيفية تصرفك."** — مورغان هاوسل`,
