    summary_teen: 'برنامج عملي لمدة 6 أسابيع للسيطرة على أموالك من خلال الأتمتة، والإنفاق الواعي، والاستثمار منخفض التكلفة.',
    fullContent_child: `## 🚀 لا مزيد من الشعور بالذنب
لا يهتم راميت سيثي إذا اشتريت قهوة لاتيه بـ 5 دولارات. ما يهمه هو أن يكون لديك نظام يتعامل مع "الانتصارات الكبيرة" (الإيجار، الراتب، الاستثمارات) تلقائياً.

## ⚙️ نظام الأتمتة
1. **الراتب يصل.**
2. **التكاليف الثابتة (إيجار، فواتير):** 50-60%.
3. **الاستثمارات:** 10%.
4. **أهداف الادخار (سفر، زواج):** 5-10%.
5. **الإنفاق الخالي من الذنب:** 20-35%.
بمجرد إعداد هذا النظام، لن تضطر أبداً إلى "وضع ميزانية" يدوية مرة أخرى.

## 💳 اهزم البنوك
تعلم كيف تتفاوض على أسعار الفائدة لبطاقات الائتمان الخاصة بك، وكيف تجعلهم يتنازلون عن الرسوم السنوية، واستخدم المكافآت للسفر مجاناً. البنوك تربح عندما تكون كسولاً؛ فلا تكن كذلك.

## 📈 الاستثمار البسيط
أنت لا تحتاج إلى وسيط مالي. استخدم صناديق المؤشرات منخفضة التكلفة. الهدف هو إعداد النظام ونسيانه. وول ستريت تريدك أن تعتقد أن الأمر معقد حتى يتمكنوا من تحصيل الرسوم منك.

> **"العامل الوحيد والأهم لتصبح غنياً هو البدء، وليس أن تكون أذكى شخص في الغرفة."** — راميت سيثي`,
