    summary_child: 'يستكشف قوة الانطوائيين في عالم لا يستطيع التوقف عن الكلام، ويظهر كيف أن الهدوء قوة هائلة في القيادة.',
    summary_teen: 'يستكشف قوة الانطوائيين في عالم لا يستطيع التوقف عن الكلام، ويظهر كيف أن الهدوء قوة هائلة في القيادة.',
    fullContent_child: `## 🤫 قوة الانطوائي
تجادل سوزان كين بأن ثلث الأشخاص الذين نعرفهم على الأقل هم انطوائيون. إنهم يفضلون الاستماع على التحدث، يبتكرون ولكنهم يكرهون الترويج لأنفسهم، ويفضلون العمل بمفردهم على العصف الذهني الجماعي.

## 🏛️ صعود "مثالية المنفتح"
في أوائل القرن العشرين، انتقلنا من ثقافة الشخصية (التركيز على الأخلاق الداخلية) إلى ثقافة الشخصية الجذابة (التركيز على كيف يراك الآخرون). خلق هذا "مثالية المنفتح" — الاعتقاد بأن الذات المثالية هي اجتماعية ومستعدة دائماً للأضواء.

## 💡 أسطورة التفكير الجماعي
جلسات العصف الذهني غالباً ما تكون أقل فعالية من عمل الأفراد بمفردهم. يزدهر الانطوائيون في "الممارسة المتعمدة"، والتي تتطلب العزلة والتركيز العميق.

## 🤝 كيف تزدهر
إذا كنت انطوائياً، لا تحاول أن تكون منفتحاً. بدلاً من ذلك، ابحث عن "مناطق استعادة الطاقة" — أماكن أو أوقات يمكنك فيها أن تكون على طبيعتك وتستعيد طاقتك.

> **"لا يوجد ارتباط إطلاقاً بين كونك المتحدث الأفضل وامتلاكك لأفضل الأفكار."** — سوزان كين`,
