    summary_child: 'يستكشف كيف يرى "الأصليون" العالم بشكل مختلف وكيف يمكن لأي شخص أن يتبنى أفكاراً جديدة ويحارب التفكير الجماعي.',
    summary_teen: 'يستكشف كيف يرى "الأصليون" العالم بشكل مختلف وكيف يمكن لأي شخص أن يتبنى أفكاراً جديدة ويحارب التفكير الجماعي.',
    fullContent_child: `## 🎨 من هو "الأصلي"؟
الأصليون هم الأشخاص الذين يأخذون المبادرة لجعل رؤاهم حقيقة. لم يولدوا بـ "جين إبداعي"؛ بل اختاروا ببساطة رفض الوضع الافتراضي والبحث عن طريقة أفضل.

## 🐢 فضائل التسويف
بينما تخبرك معظم الكتب بضرورة "البدء فوراً"، يظهر آدم غرانت أن التسويف المعتدل يمكن أن يعزز الإبداع فعلياً. فهو يسمح لعقلك بالعمل على المشكلة في الخلفية (فترة الحضانة).

## 📉 إدارة المخاطر
الأصليون ليسوا في الحقيقة "متهورين". معظمهم حذرون جداً. إنهم يوازنون بين مخاطرة كبيرة في منطقة واحدة من حياتهم (مثل بدء عمل تجاري) وحذر شديد في منطقة أخرى (مثل الاحتفاظ بوظيفتهم اليومية).

## 🗣️ إيصال صوتك
لكي يتم سماع أفكارك، يجب تكرارها. "تأثير التعرض المحض" يعني أن الناس يحبون الأفكار أكثر كلما أصبحت مألوفة لديهم. لا تستسلم بعد الرفض الأول.

> **"الأشخاص الأكثر إبداعاً هم الذين يفشلون أكثر من غيرهم، لأنهم هم الذين يحاولون أكثر من غيرهم."** — آدم غرانت`,
