    summary_child: 'قصة كيف بنى والت ديزني "ديزني لاند"، متغلباً على الخراب المالي والتحديات التقنية لإنشاء "أجمل مكان على الأرض".',
    summary_teen: 'قصة كيف بنى والت ديزني "ديزني لاند"، متغلباً على الخراب المالي والتحديات التقنية لإنشاء "أجمل مكان على الأرض".',
    fullContent_child: `## 🏰 الحلم المستحيل
في أوائل الخمسينيات، اعتقد الجميع أن والت ديزني مجنون. أراد بناء "مدينة ملاهي" ضخمة تكون نظيفة وآمنة وساحرة. رفضت البنوك تمويله، وكان شقيقه روي متشككاً.

## 🎢 بناء السحر
لتمويل ديزني لاند، عقد والت صفقة مع ABC لإنتاج برنامج تلفزيوني أسبوعي. ثم جمع فريقاً من "Imagineers" — فنانين ومهندسين ومصممي ديكور — لتحويل 160 فداناً من بساتين البرتقال إلى عالم من الخيال.

## 🧪 عقلية "التحسين المستمر" (Plussing)
لم يكن والت راضياً أبداً. حتى في يوم الافتتاح، كان يفكر بالفعل في كيفية تحسين الحديقة. أطلق على هذا اسم "Plussing". إذا كانت اللعبة جيدة، أراد جعلها رائعة. إذا كانت الحديقة جميلة، أراد جعلها مذهلة.

## ✨ الاهتمام بـ "السحر"
كان والت يتجول في الحديقة ويلاحظ أصغر التفاصيل. تأكد من وضع صناديق القمامة على المسافة الدقيقة التي سيمشيها الشخص قبل أن يرغب في رمي شيء ما. كان يؤمن بأن تجربة الضيوف مقدسة وأنه لا توجد تفاصيل صغيرة يمكن تجاهلها.

> **"ديزني لاند لن تكتمل أبداً. ستستمر في النمو طالما بقي هناك خيال في العالم."** — والت ديزني`,
